function bruteForce(roads, start, goal) {
  // BFS/DFS enumerate all simple paths (small graphs only), pick best by (cost,hops,lexicographic)
  const adj = new Map();
  for (const r of roads) {
    if (!adj.has(r.from)) adj.set(r.from, []);
    adj.get(r.from).push(r);
  }
  let best = null;
  function seqKey(depots) { return depots.join("\u0000"); }
  function better(a,b) {
    if (a.cost !== b.cost) return a.cost - b.cost;
    if (a.hops !== b.hops) return a.hops - b.hops;
    return seqKey(a.depots).localeCompare(seqKey(b.depots));
  }
  function dfs(node, path, cost, visited) {
    if (node === goal) {
      const cand = { depots: [...path], cost, hops: path.length - 1 };
      if (!best || better(cand, best) < 0) best = cand;
      // don't return; could still continue through goal to elsewhere then never come back; simple paths only
    }
    for (const r of (adj.get(node) || [])) {
      if (visited.has(r.to)) continue;
      visited.add(r.to);
      path.push(r.to);
      dfs(r.to, path, cost + r.cost, visited);
      path.pop();
      visited.delete(r.to);
    }
  }
  dfs(start, [start], 0, new Set([start]));
  return best ? { depots: best.depots, cost: best.cost } : null;
}

