import { normalizeLocation, normalizeSku, reportSku, sortKeys } from "./normalize.ts";
import type { InventoryChange, StockRow } from "./types.ts";

type Entry = {
  sku: string;
  location: string;
  qty: number;
};

function buildEntries(rows: readonly StockRow[]): Map<string, Entry> {
  const entries = new Map<string, Entry>();
  for (const row of rows) {
    const location = normalizeLocation(row.location);
    const mapKey = `${normalizeSku(row.sku)}\u0000${location}`;
    const existing = entries.get(mapKey);
    if (existing) {
      existing.qty += row.qty;
    } else {
      entries.set(mapKey, { sku: reportSku(row.sku), location, qty: row.qty });
    }
  }
  return entries;
}

export function diffInventory(before: readonly StockRow[], after: readonly StockRow[]): InventoryChange[] {
  const beforeEntries = buildEntries(before);
  const afterEntries = buildEntries(after);

  const added: InventoryChange[] = [];
  const changed: InventoryChange[] = [];
  const removed: InventoryChange[] = [];

  const afterOnly: Entry[] = [];
  const both: Array<{ key: string; entry: Entry }> = [];
  for (const [key, entry] of afterEntries) {
    if (beforeEntries.has(key)) {
      both.push({ key, entry });
    } else {
      afterOnly.push(entry);
    }
  }
  afterOnly.sort(sortKeys);
  for (const entry of afterOnly) {
    added.push({ kind: "added", sku: entry.sku, location: entry.location, qty: entry.qty });
  }

  both.sort((a, b) => sortKeys(a.entry, b.entry));
  for (const { key, entry } of both) {
    const beforeQty = beforeEntries.get(key)!.qty;
    const afterQty = entry.qty;
    if (beforeQty !== afterQty) {
      changed.push({ kind: "changed", sku: entry.sku, location: entry.location, beforeQty, afterQty, delta: afterQty - beforeQty });
    }
  }

  const removedOnly: Entry[] = [];
  for (const [key, entry] of beforeEntries) {
    if (!afterEntries.has(key)) removedOnly.push(entry);
  }
  removedOnly.sort(sortKeys);
  for (const entry of removedOnly) {
    removed.push({ kind: "removed", sku: entry.sku, location: entry.location, qty: entry.qty });
  }

  return [...added, ...changed, ...removed];
}
